                       ORG $808000

;               LABEL: CODE                       ;ORIGINAL GAME CODE ADDRESS|INTERMEDIATE ADDRESS
; ============================================================
;  RESET / boot
;    Entered from the emulation RESET vector. Switches to native
;    mode, sets up stack & direct page (D=0), clears WRAM, then
;    runs the boot init chain and falls into the main game loop.
; ============================================================
Reset:
                JML.L Boot                                      ;808000|808010   ; RESET vector entry

                db $5C,$C2,$BC,$80,$00,$00,$00,$00              ;808004|
            db $00,$00,$00,$00                                  ;80800C|

; --------------------------------------------------------
;  Boot   [12 ins, returns ?]
;    callers: Reset
;    calls:     InitPpuRegisters, InitScreenMode, sub_808797
; --------------------------------------------------------
Boot:
                CLC                                             ;808010|
                XCE                                             ;808011|
                PHK                                             ;808012|
                PLB                                             ;808013|
                REP #$30                                        ;808014|
                LDA.W #$0000                                    ;808016|
                TCD                                             ;808019|
                LDA.W #$01FF                                    ;80801A|
                TCS                                             ;80801D|
                JSL.L InitPpuRegisters                          ;80801E|818000
                JSL.L InitScreenMode                            ;808022|818089
                JSR.W sub_808797                                ;808026|808797

; --------------------------------------------------------
;  Boot_ClearWram   [24 ins, returns ?]
;    callers: irqcfg_808968
;    writes:    zp_00
;    calls:     InitGameState, input_8089CF, ScreenReinitHdmaOff, irqcfg_809202, WindowWipeThenHdmaOff
; -------------------               -------------------------------------
Boot_ClearWram:
                LDA.W #$0000                                    ;808029|
                LDY.W #$0000                                    ;80802C|

         .loop: STA.W zp_00,Y                                   ;80802F|800000
                INY                                             ;808032|
                INY                                             ;808033|
                CPY.W #$0200                                    ;808034|
                BCC .loop                                       ;808037|80802F

                LDY.W #$0206                                    ;808039|
        .loop2: STA.W zp_00,Y                                   ;80803C|800000
                INY                                             ;80803F|
                INY                                             ;808040|
                CPY.W #$0300                                    ;808041|
                BCC .loop2                                      ;808044|80803C

;       .myloop: LDY.W #modFlags                                 ;INSERT|         ;clear all wram vars that I have added
;                STA.W zp_00,Y                                   ;INSERT|800000
;                INY                                             ;INSERT|
;                INY                                             ;INSERT|
;                CPY.W #modFlags+2                               ;INSERT|         ;I only have one var rn...
;                BCC .myloop                                     ;INSERT|INSERT

                LDY.W #$032E                                    ;808046|
        .loop3: STA.W zp_00,Y                                   ;808049|800000
                INY                                             ;80804C|
                INY                                             ;80804D|
                CPY.W #$0000                                    ;80804E|
                BCC .loop3                                      ;808051|808049
                JSL.L InitGameState                             ;808053|81809E
                JSR.W input_8089CF                              ;808057|8089CF
                JSR.W ScreenReinitHdmaOff                       ;80805A|809ACC
                JSR.W irqcfg_809202                             ;80805D|809202
                JSR.W WindowWipeThenHdmaOff                     ;808060|808E33

; -------------------               -------------------------------------
;  MainLoop_Reinit                  [10 ins, returns ?]
;    callers: vbwait_               808081
;    reads:     gameM               odeFlags
;    calls:     LoadI               nitialGfx, vbwait_808741, ComputeButtonEdges, input_8082F6, GiveUpDialog_TriggerGate, input_80814E, +1 more
;
;    RECON NOTE (trace-assisted, see level_loading_recon.md): gameModeFlags
;    is a small bitfield; the only two values seen across all 5 traces:
;      bit0 ($0001) set, all others clear -- Level 1 and Level 2 both
;                    read this way (i.e. it just marks "in a level",
;                    not which one -- see currentSceneId for that).
;      bit2 ($0004) set, all others clear -- observed the whole time
;                    on the Try Again screen and (per the read at
;                    ScreenReinitHdmaOff's scene-copy) on Game Over.
;                    Likely the general "static/menu-type screen" flag.
;    Bit3 ($0008, tested right below to choose MainLoop_PauseOrMenu)
;    was never observed set in any trace, so MainLoop_PauseOrMenu's
;    actual trigger/purpose is NOT confirmed -- our best guess is a
;    true pause menu (not exercised by any of the 5 captured
;    scenarios), but that's a guess, not a finding.
; --------------------------------------------------------
MainLoop_Reinit:
                JSL.L LoadInitialGfx                           ;808063|818190
                JSR.W vbwait_808741                            ;808067|808741
                JSR.W ComputeButtonEdges                       ;80806A|80925C
                JSR.W input_8082F6                             ;80806D|8082F6
                JSR.W GiveUpDialog_TriggerGate                 ;808070|8083B6
                JSR.W input_80814E                             ;808073|80814E
                LDA.W gameModeFlags                            ;808076|8019E3
                BIT.W #$0008                                   ;808079|
                BEQ vbwait_808081                              ;80807C|808081
                JMP.W MainLoop_PauseOrMenu                     ;80807E|80811B


; --------------------------------------------------------
;  vbwait_808081   [51 ins, returns ?]
;    callers: vbwait_808081
;    writes:    vblankCmd
;    reads:     vblankCmd, gameModeFlags
;    calls:     input_80B529, farsub_8182B2, sub_8086E1, RunCircleIrisHdma, UpdateAllObjects, sub_80ECA9, +27 more
