;======================================================================
; INTERRUPT HANDLERS
;======================================================================
; --------------------------------------------------------
;  NMI   [1 ins, returns ?]
;    calls:     NMI_Handler
; --------------------------------------------------------
NMI:
                JML.L NMI_Handler                              ;808AFC|808B00   ; NMI vector stub -> NMI_Handler


; ============================================================
;  NMI handler (VBlank)
;    Saves A/X/Y to $00/$02/$04, bumps frameCounter, and if the
;    NMI flag (RDNMI bit7) is set, performs the per-frame PPU
;    work: register shadows -> PPU, then dispatches one VBlank
;    task via vblankCmdTable[vblankCmd], reads the joypads, and
;    finally clears vblankCmd so the main thread can issue the
;    next one.
; ============================================================

;== hdr 808B00 ==
; ============================================================
;   NMI_Handler  --  VBlank entry (FastROM, DB=PB=80, DP=0)
; ------------------------------------------------------------
;   Per-frame flow (trace-verified, V:225+ = VBlank):
;     1. PHP/CLD/PHB/PHK/PLB/PHD, REP #$30, force DP=0,
;        save A/X/Y -> $00/$02/$04.
;     2. INC frameCounter $0338  (ALWAYS, even if NMI not real).
;     3. Gate on RDNMI $4210 bit7. If clear -> restore + RTI
;        (skip all PPU work). Trace: $4210 read = $2DA2.
;     4. ApplyVideoModeRegs $808D02 (1st flush: BG1SC/BG12NBA/
;        M7 / TM / COLDATA backdrop; branches on gameModeFlags
;        bit0).
;     5. DISPATCH: X = vblankCmd $0333 (already *2);
;        JSR (VBlankCmdTable,X). Exactly ONE task runs.
;     6. ApplyColorMathRegs $808D89 (2nd flush: CGADSUB +
;        fixed colour to CGRAM).
;     7. ReadJoypads $809281 (auto-joypad -> $03C2/$03C4).
;     8. STZ vblankCmd $0333 -> release the slot to main thread.
;   Hand-off: main loop writes vblankCmd (value*2 = 2..22) and
;   spins reading 0; NMI consumes it and zeroes it. This is the
;   single sync point a split-screen mod must preserve (it owns
;   BG1 scroll latch + the one-DMA-per-frame budget).
;   Trace: dispatch observed for cmd values 0/1/2/3.
; ============================================================
NMI_Handler:
                PHP                                            ;808B00|
                CLD                                            ;808B01|
                PHB                                            ;808B02|
                PHK                                            ;808B03|
                PLB                                            ;808B04|
                PHD                                            ;808B05|
                REP #$30                                       ;808B06|
                PEA.W $0000                                    ;808B08|
                PLD                                            ;808B0B|
                STA.B zp_00                                    ;808B0C|000000
                STX.B zp_02                                    ;808B0E|000002
                STY.B zp_04                                    ;808B10|000004
                INC.W frameCounter                             ;808B12|800338   ; ++frameCounter   ; ++frameCounter (every NMI, before the RDNMI gate)
                LDA.W RDNMI                                    ;808B15|804210   ; RDNMI: was an NMI actually asserted?   ; RDNMI bit7: real NMI? If 0, skip all PPU work (BEQ +)
                BIT.W #$0080                                   ;808B18|
                BEQ .skip                                      ;808B1B|808B2F
                JSR.W ApplyVideoModeRegs                       ;808B1D|808D02   ; 1st shadow flush: video-mode/BG-base/TM/COLDATA
                LDX.W vblankCmd                                ;808B20|800333
                JSR.W (VBlankCmdTable,X)                       ;808B23|808B39   ; dispatch vblankCmdTable[vblankCmd]   ; dispatch: run exactly one VBlankCmdTable[vblankCmd]
                JSR.W ApplyColorMathRegs                       ;808B26|808D89   ; 2nd shadow flush: CGADSUB + fixed colour
                JSR.W ReadJoypads                              ;808B29|809281   ; consume auto-joypad read -> $03C2/$03C4
                STZ.W vblankCmd                                ;808B2C|800333   ; issue VBlank command to NMI   ; clear vblankCmd: release the slot to the main thread

         .skip: LDA.B zp_00                                    ;808B2F|000000
                LDX.B zp_02                                    ;808B31|000002
                LDY.B zp_04                                    ;808B33|000004
                PLD                                            ;808B35|
                PLB                                            ;808B36|
                PLP                                            ;808B37|

Brk_Cop_Return:
                RTI                                            ;808B38|   ; COP/BRK/ABORT vector target (bare RTI)

VBlankCmdTable:
                dw VBlank_Nop                                  ;808B39|808B51   ; jump table indexed by vblankCmd in the NMI
                dw VBlank_Flush_DmaA                           ;808B3B|808B52
                dw VBlank_Flush_DmaB                           ;808B3D|808B79
                dw VBlank_Flush_Tilemap                        ;808B3F|808BA0
                dw VBlank_Cgram_Oam_DmaC                       ;808B41|808BEA
                dw VBlank_Cgram_TilemapStream                  ;808B43|808BF3
                dw VBlank_Cgram_Only                           ;808B45|808BF9
                dw VBlank_TilemapStream_Only                   ;808B47|808BFC
                dw VBlank_Nop                                  ;808B49|808B51
                dw VBlank_Nop                                  ;808B4B|808B51
                dw VBlank_Task4_DmaA                           ;808B4D|808BC5
                dw VBlank_UpdateMode7HdmaPtrs                  ;808B4F|808BC8

VBlank_Nop:
                RTS                                            ;808B51|   ; vblankCmd handler: do nothing


; --------------------------------------------------------
;  VBlank_Flush_DmaA   [15 ins, returns ?]
;    calls:     VramDmaBlockA, FlushVramWordWrites, RunDeferredFarCall, VramDmaBlockC, UploadOamTables, StreamTilemap, +3 more
; --------------------------------------------------------

;== hdr 808B52 ==
; ------------------------------------------------------------
;   VBlank Tasks 1/2/3 -- 'one DMA per frame' priority chain
; ------------------------------------------------------------
;   Each is a JSR/BCS ladder of work-units. A unit returns:
;     carry CLEAR -> nothing pending, try the next unit;
;     carry SET   -> it issued this frame's single DMA/upload,
;                    so BRANCH to the common tail.
;   (Trace-verified at 808B55: BCS taken with C set when the
;    unit did work, not taken with C clear otherwise.)
;   Common tail (unconditional per-frame work):
;     OamDmaUpload  $80E18D (OAM low+high via DMA ch1/ch4)
;     LatchBgScroll $80BFE0 (BG1 scroll shadow -> BG1HOFS,
;                           skipped when gameModeFlags bit0=1)
;   Task3 additionally kicks StartCgramDma before the scroll
;   latch. Leads differ: Task1 = VramDmaBlockA, Task2 =
;   VramDmaBlockB ($19E8+$0800), Task3 = ProcessTilemapEdits.
;   Round-robin across frames uploads different regions while
;   staying within the ~one-block-per-VBlank DMA budget.
VBlank_Flush_DmaA:
                JSR.W VramDmaBlockA                       ;808B52|80DF35
                BCS .skip                                      ;808B55|808B73   ; carry set => VramDmaBlockA consumed the DMA slot -> tail
                JSR.W FlushVramWordWrites                      ;808B57|80A369
                BCS .skip                                      ;808B5A|808B73
                JSR.W RunDeferredFarCall                       ;808B5C|808BFF
                BCS .skip                                      ;808B5F|808B73
                JSR.W VramDmaBlockC                            ;808B61|80B31C
                BCS .skip                                      ;808B64|808B73
                JSR.W UploadOamTables                          ;808B66|80BAED
                BCS .skip                                      ;808B69|808B73
                JSR.W StreamTilemap                            ;808B6B|8089E1
                BCS .skip                                      ;808B6E|808B73
                JSR.W NopRts                                   ;808B70|8089E0

         .skip: JSR.W OamDmaUpload                             ;808B73|80E18D   ; common tail: OAM DMA then BG scroll latch
                JMP.W LatchBgScroll                            ;808B76|80BFE0


; --------------------------------------------------------
;  VBlank_Flush_DmaB   [15 ins, returns ?]
;    calls:     PendingMapFillDma, FlushVramWordWrites, RunDeferredFarCall, VramDmaBlockC, UploadOamTables, StreamTilemap, +3 more
; --------------------------------------------------------
VBlank_Flush_DmaB:
                JSR.W PendingMapFillDma                   ;808B79|80DF50
                BCS .skip                                      ;808B7C|808B9A
                JSR.W FlushVramWordWrites                      ;808B7E|80A369
                BCS .skip                                      ;808B81|808B9A
                JSR.W RunDeferredFarCall                       ;808B83|808BFF
                BCS .skip                                      ;808B86|808B9A
                JSR.W VramDmaBlockC                            ;808B88|80B31C
                BCS .skip                                      ;808B8B|808B9A
                JSR.W UploadOamTables                          ;808B8D|80BAED
                BCS .skip                                      ;808B90|808B9A
                JSR.W StreamTilemap                            ;808B92|8089E1
                BCS .skip                                      ;808B95|808B9A
                JSR.W NopRts                                   ;808B97|8089E0

         .skip: JSR.W OamDmaUpload                             ;808B9A|80E18D
                JMP.W LatchBgScroll                            ;808B9D|80BFE0


; --------------------------------------------------------
;  VBlank_Flush_Tilemap   [14 ins, returns ?]
;    calls:     ProcessTilemapEdits, FlushVramWordWrites, RunDeferredFarCall, VramDmaBlockC, StreamTilemap, NopRts, +3 more
; --------------------------------------------------------
VBlank_Flush_Tilemap:
                JSR.W ProcessTilemapEdits              ;808BA0|80C04B
                BCS .skip                                      ;808BA3|808BBC
                JSR.W FlushVramWordWrites                      ;808BA5|80A369
                BCS .skip                                      ;808BA8|808BBC
                JSR.W RunDeferredFarCall                       ;808BAA|808BFF
                BCS .skip                                      ;808BAD|808BBC
                JSR.W VramDmaBlockC                            ;808BAF|80B31C
                BCS .skip                                      ;808BB2|808BBC
                JSR.W StreamTilemap                            ;808BB4|8089E1
                BCS .skip                                      ;808BB7|808BBC
                JSR.W NopRts                                   ;808BB9|8089E0

         .skip: JSR.W OamDmaUpload                             ;808BBC|80E18D
                JSR.W StartCgramDma                            ;808BBF|808C2A   ; Task3 extra: kick CGRAM DMA (ch2)
                JMP.W LatchBgScroll                            ;808BC2|80BFE0


; --------------------------------------------------------
;  VBlank_Task4_DmaA   [1 ins, returns ?]
;    calls:     VramDmaBlockA
; --------------------------------------------------------
VBlank_Task4_DmaA:
                JMP.W VramDmaBlockA                       ;808BC5|80DF35


; --------------------------------------------------------
;  VBlank_UpdateMode7HdmaPtrs   [15 ins, returns RTS]
;    writes HW: A1TL0, A1TL3, A1TL6, A1TL7
;    writes:    m7HdmaSrc, m7HdmaTablePtr
;    reads:     m7HdmaTablePtr
;    calls:     PendingMapFillDma
; --------------------------------------------------------

;== hdr 808BC8 ==
; VBlank_UpdateMode7HdmaPtrs -- per-frame re-point of the MODE-7 matrix HDMA.
;
; VBlank task (jump-table entry at 808B4F). First calls PendingMapFillDma
; (one-shot ch5 VRAM fill if flagged). Then it walks m7HdmaTablePtr ($9E)
; through this frame's per-scanline Mode-7 matrix tables in bank $7F
; ($1C4 bytes per channel) and loads their start offsets into the A1TL
; source-low registers of HDMA channels 0,3,6,7:
;    table0 -> A1TL0 ($4302) AND A1TL7 ($4372)   (= m7HdmaSrc $94)
;    table1 -> A1TL3 ($4332)   (m7HdmaSrc + $1C4)
;    table2 -> A1TL6 ($4362)   (m7HdmaSrc + $1C4*2)
;    m7HdmaTablePtr += $1C4*3 (=$54C) for next frame
; Channels 0/3/6/7 are configured once by SetupMode7MatrixHdma ($8098F9):
; BGMODE=7, DMAP=$0A HDMA -> M7A-M7D ($211B-$211E), A1B bank=$7F, HDMAEN=$C9.
; This is the Mode-7 MATRIX feed (per-scanline rotate/scale) -- NOT scroll
; and NOT the tilemap VRAM upload (that is the channel-0 GP-DMA cluster below).
;
; *** NOT exercised in the 25GB gameplay trace: levels run BGMODE 0 and never
; reach this path -- it is for a Mode-7 screen (intro/logo/transition) not
; captured. Implication for the split-screen mod: HDMA channels 0/3/6/7 are
; FREE during normal levels. The GAMEPLAY HDMA is a separate setup at
; $808E33 (HDMAEN=$8D -> channels 0,2,3,7; ch3 -> $2126 window). ***
VBlank_UpdateMode7HdmaPtrs:
                JSR.W PendingMapFillDma                  ;808BC8|80DF50   ; re-point Mode-7 matrix HDMA tables (ch0/3/6/7)
                LDA.B m7HdmaTablePtr                           ;808BCB|00009E
                STA.B m7HdmaSrc                                ;808BCD|000094
                STA.W A1TL0                                    ;808BCF|804302   ; Re-point ch0 A1T-low ($4302) at this frame's $7F table; same value to ch7 ($4372); +$01C4 -> ch3 ($4332), +$01C4 -> ch6 ($4362). These are the Mode-7 HDMA channels' A1T.
                STA.W A1TL7                                    ;808BD2|804372
                CLC                                            ;808BD5|
                ADC.W #$01C4                                   ;808BD6|   ; CLC then +$01C4 = next channel table; A1TL3 (ch3) at 808BD9, A1TL6 (ch6) at 808BE0
                STA.W A1TL3                                    ;808BD9|804332
                CLC                                            ;808BDC|
                ADC.W #$01C4                                   ;808BDD|
                STA.W A1TL6                                    ;808BE0|804362
                CLC                                            ;808BE3|
                ADC.W #$01C4                                   ;808BE4|
                STA.B m7HdmaTablePtr                           ;808BE7|00009E
                RTS                                            ;808BE9|


; --------------------------------------------------------
;  VBlank_Cgram_Oam_DmaC   [3 ins, returns ?]
;    calls:     StartCgramDma, UploadOamTables, VramDmaBlockC
; --------------------------------------------------------
VBlank_Cgram_Oam_DmaC:
                JSR.W StartCgramDma                   ;808BEA|808C2A
                JSR.W UploadOamTables                          ;808BED|80BAED
                JMP.W VramDmaBlockC                            ;808BF0|80B31C


; --------------------------------------------------------
;  VBlank_Cgram_TilemapStream   [2 ins, returns ?]
;    calls:     StartCgramDma, StreamTilemap
; --------------------------------------------------------
VBlank_Cgram_TilemapStream:
                JSR.W StartCgramDma              ;808BF3|808C2A
                JMP.W StreamTilemap                            ;808BF6|8089E1


; --------------------------------------------------------
;  VBlank_Cgram_Only   [1 ins, returns ?]
;    calls:     StartCgramDma
; --------------------------------------------------------
VBlank_Cgram_Only:
                JMP.W StartCgramDma                       ;808BF9|808C2A


; --------------------------------------------------------
;  VBlank_TilemapStream_Only   [1 ins, returns ?]
;    calls:     StreamTilemap
; --------------------------------------------------------
VBlank_TilemapStream_Only:
                JMP.W StreamTilemap               ;808BFC|8089E1


; --------------------------------------------------------
;  RunDeferredFarCall   [25 ins, returns RTS]
;    callers: VBlank_Flush_DmaA, VBlank_Flush_DmaB, VBlank_Flush_Tilemap
;    writes:    deferredFarCallAddr
;    reads:     deferredFarCallAddr, deferredFarCallBank
; --------------------------------------------------------
RunDeferredFarCall:
                LDA.W deferredFarCallAddr                      ;808BFF|8003AA   ; if a far routine was queued ($03AA/$03AC), call it
                BNE +                                          ;808C02|808C06
                CLC                                            ;808C04|
                RTS                                            ;808C05|


             +: PHB                                            ;808C06|
                PHK                                            ;808C07|
                PEA.W .exit                                    ;808C08|808C21
                SEP #$20                                       ;808C0B|
                LDA.W deferredFarCallBank                      ;808C0D|8003AC
                PHA                                            ;808C10|
                REP #$20                                       ;808C11|
                LDA.W deferredFarCallAddr                      ;808C13|8003AA
                DEC A                                          ;808C16|
                PHA                                            ;808C17|
                SEP #$30                                       ;808C18|
                LDA.W deferredFarCallBank                      ;808C1A|8003AC
                PHA                                            ;808C1D|
                PLB                                            ;808C1E|
                REP #$30                                       ;808C1F|

         .exit: RTL                                            ;808C21|

                REP #$30                                       ;808C22|
                PLB                                            ;808C24|
                STZ.W deferredFarCallAddr                      ;808C25|8003AA
                SEC                                            ;808C28|
                RTS                                            ;808C29|


; --------------------------------------------------------
;  StartCgramDma   [6 ins, returns RTS]
;    callers: VBlank_Flush_Tilemap, VBlank_Cgram_Oam_DmaC, VBlank_Cgram_TilemapStream, VBlank_Cgram_Only
;    writes HW: CGADD, MDMAEN
; --------------------------------------------------------
StartCgramDma:
                SEP #$20                                       ;808C2A|   ; kick general-purpose DMA channel 2 (CGRAM upload)   ; CGADD=0, trigger GP-DMA ch2 (CGRAM upload)
                STZ.W CGADD                                    ;808C2C|802121
                LDA.B #$04                                     ;808C2F|
                STA.W MDMAEN                                   ;808C31|80420B   ; trigger GP-DMA (MDMAEN)
                REP #$20                                       ;808C34|
                RTS                                            ;808C36|


; --------------------------------------------------------
;  IRQ   [1 ins, returns ?]
;    calls:     IRQ_Handler
; --------------------------------------------------------
IRQ:
                JML.L IRQ_Handler                              ;808C37|808C3B   ; IRQ/BRK vector stub -> IRQ_Handler


; ============================================================
;  IRQ_Handler  --  raster split (H/V-timer IRQ)
; ------------------------------------------------------------
;  This is the mid-screen "split" that reconfigures BG1 partway
;  down the frame (the natural hook a split-screen mod extends).
;
;  Prologue saves full state, forces DP=0 (PEA $0000/PLD) and
;  saves A/X/Y to $00/$02/$04. It then ACKs the IRQ by reading
;  TIMEUP ($4211) and testing bit7; if bit7=0 this wasn't our
;  H/V-timer IRQ, so it just restores and RTIs.
;
;  When it IS our IRQ, the split runs only if:
;     rasterIrqActive ($0335) == 0     (no custom effect owns it)
;     gameModeFlags  ($19E3) bit0 == 1 (the split-screen layout)
;  Otherwise it defers to the far handler JSL $858000 and exits.
;
;  The split is a 2-phase ping-pong driven by rasterSplitPhase
;  ($03F4) and re-arming VTIME ($4209) each time:
;     phase 0 -> set phase=1, VTIME=$2F (47), exit  (arm 2nd IRQ)
;     phase 1 -> set phase=0, VTIME=$2D (45),
;                JSR ApplyRasterSplitRegs (do the visible change)
;
;  TRACE-VERIFIED: the IRQ fires at scanline V=45 ($2D); $4211
;  bit7 ACK and the VTIME re-arm both observed in
;  traces/LostVikings-trace.log. (That capture is a menu/password
;  screen, so the ApplyRasterSplitRegs path itself didn't run --
;  capture an in-level trace to watch the BG1 reprogram fire.)
; ============================================================
IRQ_Handler:
                PHP                                            ;808C3B|
                PHB                                            ;808C3C|
                PHK                                            ;808C3D|
                PLB                                            ;808C3E|
                PHD                                            ;808C3F|
                CLD                                            ;808C40|
                REP #$30                                       ;808C41|
                PEA.W $0000                                    ;808C43|
                PLD                                            ;808C46|
                STA.B zp_00                                    ;808C47|000000
                STX.B zp_02                                    ;808C49|000002
                STY.B zp_04                                    ;808C4B|000004
                SEP #$30                                       ;808C4D|
                LDA.W TIMEUP                                   ;808C4F|804211   ; TIMEUP: acknowledge the IRQ
                AND.B #$80                                     ;808C52|
                BEQ .exit                                      ;808C54|808C86
                LDA.W rasterIrqActive                          ;808C56|800335   ; rasterSplitOwner: !=0 -> custom effect owns IRQ
                BNE .skip                                      ;808C59|808C82   ;   ...so skip the default split, just run $858000
                LDA.W gameModeFlags                            ;808C5B|8019E3
                BIT.B #$01                                     ;808C5E|         ; bit0 = split-screen / alt video layout active?
                BEQ .skip                                      ;808C60|808C82   ; not in split layout -> skip

                       ;changeLineDown
                LDA.W rasterSplitPhase                         ;808C62|8003F4   ; rasterSplitPhase (0 = arm phase, 1 = apply phase)
                BNE .changeLineUp                              ;808C65|808C74
                INC.W rasterSplitPhase                         ;808C67|8003F4   ; phase 0 -> 1
                LDA.B #$2F                                     ;808C6A|         ; next IRQ at scanline $2F (47)...
                STA.W VTIMEL                                   ;808C6C|804209   ; ...re-arm VTIME (low)
                STZ.W VTIMEH                                   ;808C6F|80420A   ; VTIME high = 0
                BRA .exit                                      ;808C72|808C86   ; exit; the apply happens on the NEXT IRQ

 .changeLineUp: STZ.W rasterSplitPhase                         ;808C74|8003F4   ; phase 1 -> 0 (ping-pong reset)
                LDA.B #$2D                                     ;808C77|         ; next IRQ at scanline $2D (45, trace-verified)
                STA.W VTIMEL                                   ;808C79|804209
                STZ.W VTIMEH                                   ;808C7C|80420A
                JSR.W ApplyRasterSplitRegs                     ;808C7F|808C92   ; -> ApplyRasterSplitRegs: reprogram BG1 for lower region

         .skip: JSL.L sub_858000                               ;808C82|858000   ; far raster/extra-effect handler (bank 85)

         .exit: REP #$30                                       ;808C86|
                LDA.B zp_00                                    ;808C88|000000   ; restore stuff
                LDX.B zp_02                                    ;808C8A|000002
                LDY.B zp_04                                    ;808C8C|000004
                PLD                                            ;808C8E|
                PLB                                            ;808C8F|
                PLP                                            ;808C90|
                RTI                                            ;808C91|


; --------------------------------------------------------
;  ApplyRasterSplitRegs   [40 ins, returns RTS]  (auto-named pal_808C92)
;    callers: IRQ_Handler (phase-1 raster split)
;    NOTE: auto-named "pal_" because it touches CGDATA, but this
;    is really the whole-BG1 reconfigure for the LOWER split
;    region -- the visible half of the raster split. It rewrites:
;       INIDISP=$8F (full brightness, blank off)
;       BG1SC  <- bg1scSplitShadow ($19EB)|1  (lower tilemap base/size)
;       BG12NBA<- $033C                       (lower BG char base)
;       BG1HOFS/BG1VOFS <- bg1Scroll* shadows (re-latch scroll)
;       TM     <- mainScreenShadow
;       COLDATA R/G/B and CGRAM colour index 3 (backdrop for region)
;    Brackets the writes with WaitForHBlank (h-blank/timing sync) so
;    the register changes land in the gap between scanlines.
;    >> For a split-screen mod this is the template: a per-region
;       PPU re-program executed from the raster IRQ. <<
;    writes HW: BG12NBA, BG1HOFS, BG1SC, BG1VOFS, CGADD, CGDATA, COLDATA, INIDISP, TM
;    reads:     inidispShadow, ram_033C, backdropColorR, backdropColorG, backdropColorB, backdropColorR2 ...
;    calls:     WaitForHBlank
; --------------------------------------------------------
ApplyRasterSplitRegs:
                JSR.W WaitForHBlank                  ;808C92|808DE1   ; h-blank / timing sync before reg writes
                LDA.B #$8F                                     ;808C95|
                STA.W INIDISP                                  ;808C97|802100
                LDA.W ram_19EB                                 ;808C9A|8019EB
                ORA.B #$01                                     ;808C9D|
                STA.W BG1SC                                    ;808C9F|802107
                LDA.W ram_033C                                 ;808CA2|80033C
                STA.W BG12NBA                                  ;808CA5|80210B
                LDA.W bg1ScrollXLo                             ;808CA8|8016BD
                STA.W BG1HOFS                                  ;808CAB|80210D
                LDA.W bg1ScrollXHi                             ;808CAE|8016BE
                STA.W BG1HOFS                                  ;808CB1|80210D
                LDA.W bg1ScrollYLo                             ;808CB4|8016BF
                STA.W BG1VOFS                                  ;808CB7|80210E
                LDA.W bg1ScrollYHi                             ;808CBA|8016C0
                STA.W BG1VOFS                                  ;808CBD|80210E
                LDA.W mainScreenShadow                         ;808CC0|800394
                STA.W TM                                       ;808CC3|80212C
                LDA.W backdropColorR                           ;808CC6|800344
                ORA.W backdropColorR2                          ;808CC9|80034A
                ORA.B #$20                                     ;808CCC|
                STA.W COLDATA                                  ;808CCE|802132
                LDA.W backdropColorG                           ;808CD1|800346
                ORA.W backdropColorG2                          ;808CD4|80034C
                ORA.B #$40                                     ;808CD7|
                STA.W COLDATA                                  ;808CD9|802132
                LDA.W backdropColorB                           ;808CDC|800348
                ORA.W backdropColorB2                          ;808CDF|80034E
                ORA.B #$80                                     ;808CE2|
                STA.W COLDATA                                  ;808CE4|802132
                LDA.B #$03                                     ;808CE7|
                STA.W CGADD                                    ;808CE9|802121
                LDA.W dialogueBoxColorLo                       ;808CEC|8019BB
                STA.W CGDATA                                   ;808CEF|802122
                LDA.W dialogueBoxColorHi                       ;808CF2|8019BC
                STA.W CGDATA                                   ;808CF5|802122
                JSR.W WaitForHBlank                            ;808CF8|808DE1
                LDA.W inidispShadow                            ;808CFB|800330
                STA.W INIDISP                                  ;808CFE|802100
                RTS                                            ;808D01|


; ------------------------------------------------------------
;  ApplyVideoModeRegs
;    gameModeFlags bit0 selects between two screen layouts; this
;    pushes the matching BG1SC / BG12NBA / fixed-colour values.
; ------------------------------------------------------------
ApplyVideoModeRegs:
                LDA.W gameModeFlags                            ;808D02|8019E3   ; set BG1SC/BG12NBA/COLDATA depending on gameModeFlags bit0
                BIT.W #$0001                                   ;808D05|
                BEQ .nonGameMode                               ;808D08|808D3D

                SEP #$20                                       ;808D0A|
                LDA.W bg1scShadow                              ;808D0C|8019EF
                STA.W BG1SC                                    ;808D0F|802107
                LDA.W bg12nbaShadow                            ;808D12|8019E7
                STA.W BG12NBA                                  ;808D15|80210B
                STZ.W BG1HOFS                                  ;808D18|80210D
                STZ.W BG1HOFS                                  ;808D1B|80210D
                LDA.B #$FF                                     ;808D1E|
                STA.W BG1VOFS                                  ;808D20|80210E
                STZ.W BG1VOFS                                  ;808D23|80210E
                LDA.B #$11                                     ;808D26|
                STA.W TM                                       ;808D28|80212C
                LDA.B #$20                                     ;808D2B|
                STA.W COLDATA                                  ;808D2D|802132
                LDA.B #$40                                     ;808D30|
                STA.W COLDATA                                  ;808D32|802132
                LDA.B #$80                                     ;808D35|
                STA.W COLDATA                                  ;808D37|802132
                REP #$20                                       ;808D3A|
                RTS                                            ;808D3C|


  .nonGameMode: SEP #$20                                       ;808D3D|
                LDA.W backdropColorR                           ;808D3F|800344
                ORA.W backdropColorR2                          ;808D42|80034A
                ORA.B #$20                                     ;808D45|
                STA.W COLDATA                                  ;808D47|802132
                LDA.W backdropColorG                           ;808D4A|800346
                ORA.W backdropColorG2                          ;808D4D|80034C
                ORA.B #$40                                     ;808D50|
