; --------------------------------------------------------
;  WaitForVBlankStart   [7 ins, returns RTS]
;    callers: irqcfg_808834, input_80889A, irqcfg_808968, WindowWipeThenHdmaOff, hdma_808E7E, StartWindowWipeHdma, +2 more
;    reads HW:  HVBJOY
; --------------------------------------------------------

;== hdr 808DD5 ==
; ------------------------------------------------------------
;  VBlank/HBlank wait primitives
;  (808DD5/808DE1/808DED)
;    Thin spin-waits on HVBJOY ($4212): bit7=VBlank, bit6=
;    HBlank. WaitVBlankStart waits for VBlank to begin,
;    WaitVBlankEnd for it to end, WaitHBlank for HBlank.
;    Each PHP/PLP-preserves flags. (The hottest spins of all
;    are the inline NMI-sync waits at 808145/8080EA/80809E.)
; ------------------------------------------------------------
WaitForVBlankStart:
                PHP                                    ;808DD5|
                SEP #$20                                       ;808DD6|

         .loop: LDA.W HVBJOY                                   ;808DD8|804212   ; HVBJOY bit7: wait for VBlank start
                BIT.B #$80                                     ;808DDB|
                BEQ .loop                                      ;808DDD|808DD8
                PLP                                            ;808DDF|
                RTS                                            ;808DE0|


; --------------------------------------------------------
;  WaitForHBlank   [7 ins, returns RTS]
;    callers: ApplyRasterSplitRegs
;    reads HW:  HVBJOY
; --------------------------------------------------------
WaitForHBlank:
                PHP                                         ;808DE1|
                SEP #$20                                       ;808DE2|

         .loop: LDA.W HVBJOY                                   ;808DE4|804212
                BIT.B #$40                                     ;808DE7|
                BEQ .loop                                      ;808DE9|808DE4
                PLP                                            ;808DEB|
                RTS                                            ;808DEC|


; --------------------------------------------------------
;  WaitForVBlankEnd   [17 ins, returns RTS]
;    callers: irqcfg_808834, input_80889A, irqcfg_808968, WindowWipeThenHdmaOff, hdma_808E7E, StartWindowWipeHdma
;    reads HW:  HVBJOY
; --------------------------------------------------------
WaitForVBlankEnd:
                PHP                                      ;808DED|
                SEP #$20                                       ;808DEE|

         .loop: LDA.W HVBJOY                                   ;808DF0|804212
                BIT.B #$80                                     ;808DF3|
                BNE .loop                                      ;808DF5|808DF0
                PLP                                            ;808DF7|
                RTS                                            ;808DF8|

                PHP                                            ;808DF9|
                SEP #$20                                       ;808DFA|

        .loop2: LDA.W HVBJOY                                   ;808DFC|804212
                BIT.B #$40                                     ;808DFF|
                BEQ .loop2                                     ;808E01|808DFC

        .loop3: LDA.W HVBJOY                                   ;808E03|804212
                BIT.B #$40                                     ;808E06|
                BNE .loop3                                     ;808E08|808E03
                PLP                                            ;808E0A|
                RTS                                            ;808E0B|


; ------------------------------------------------------------
;  InitOAM
;    Reset OAM: 128 sprites set off-screen (Y=$E0, tile/attr 0),
;    then 32 bytes of $AA into the high OAM table.
; ------------------------------------------------------------
InitOAM:
                STZ.W OAMADDL                                  ;808E0C|802102   ; hide all 128 sprites (Y=$E0) and reset the high OAM table
                SEP #$30                                       ;808E0F|
                LDX.B #$80                                     ;808E11|

         .loop: LDA.B #$0A                                     ;808E13|
                STA.W OAMDATA                                  ;808E15|802104
                LDA.B #$E0                                     ;808E18|
                STA.W OAMDATA                                  ;808E1A|802104
                STZ.W OAMDATA                                  ;808E1D|802104
                STZ.W OAMDATA                                  ;808E20|802104
                DEX                                            ;808E23|
                BNE .loop                                      ;808E24|808E13
                LDX.B #$20                                     ;808E26|
                LDA.B #$AA                                     ;808E28|

        .loop2: STA.W OAMDATA                                  ;808E2A|802104
                DEX                                            ;808E2D|
                BNE .loop2                                     ;808E2E|808E2A
                REP #$30                                       ;808E30|
                RTS                                            ;808E32|


; --------------------------------------------------------
;  WindowWipeThenHdmaOff   [29 ins, returns RTS]
;    callers: Boot_ClearWram, input_80814E
;    writes HW: HDMAEN
;    writes:    zp_3A
;    reads:     zp_3A, ram_19CE
;    calls:     sub_8088F8, StartWindowWipeHdma, WaitForVBlankStart, WaitForVBlankEnd, ppucfg_808F38
; --------------------------------------------------------

;== hdr 808E33 ==
; ---------------------------------------------------------------
;  WindowWipeThenHdmaOff (was hdma_808E33)
;    Runs an ANIMATED window-mask wipe: loops calling 808EE0,
;    which briefly enables channel-3 window HDMA ($420C=$08) each
;    pass; then this routine writes HDMAEN=$00 so the FINAL state
;    is HDMA-off. (Existing annotation mislabels the $808E78 write
;    as 'enable HDMA channels' -- it actually disables.)
;    $808E7E is the near-identical sibling that also fixes up
;    INIDISP / window-select regs afterward.
; ---------------------------------------------------------------
WindowWipeThenHdmaOff:
                LDA.W ram_19CE                       ;808E33|8019CE
                AND.W #$00FF                                   ;808E36|
                BNE +                                          ;808E39|808E3E
                JMP.W ppucfg_808F38                            ;808E3B|808F38


             +: LDA.W #$00D7                                   ;808E3E|
                LDX.W #$0030                                   ;808E41|
                JSR.W sub_8088F8                               ;808E44|8088F8
                LDA.L UNREACH_8185AD                           ;808E47|8185AD
                AND.W #$00FF                                   ;808E4B|
                ASL A                                          ;808E4E|
                STA.B zp_3A                                    ;808E4F|00003A
                LDY.W #$0000                                   ;808E51|
                LDX.W #$0000                                   ;808E54|

         .loop: LDA.L UNREACH_8185AE,X                         ;808E57|8185AE
                JSR.W StartWindowWipeHdma                      ;808E5B|808EE0
                LDA.L UNREACH_8185AE,X                         ;808E5E|8185AE
                JSR.W StartWindowWipeHdma                      ;808E62|808EE0
                INX                                            ;808E65|
                INX                                            ;808E66|
                CPX.B zp_3A                                    ;808E67|00003A
                BNE .loop                                      ;808E69|808E57
                SEP #$20                                       ;808E6B|
                JSR.W WaitForVBlankStart                       ;808E6D|808DD5
                JSR.W WaitForVBlankEnd                         ;808E70|808DED
                JSR.W WaitForVBlankStart                       ;808E73|808DD5
                LDA.B #$00                                     ;808E76|
                STA.W HDMAEN                                   ;808E78|80420C   ; enable HDMA channels (HDMAEN)   ; HDMAEN=$00: this write DISABLES HDMA (final state after the 808EE0 wipe loop). Existing annotation 'enable HDMA' is wrong.
                REP #$20                                       ;808E7B|
                RTS                                            ;808E7D|


; --------------------------------------------------------
