                LDA.L UNREACH_8185AD                           ;808E92|8185AD
                AND.W #$00FF                                   ;808E96|
                ASL A                                          ;808E99|
                STA.B zp_3A                                    ;808E9A|00003A
                LDY.W #$0002                                   ;808E9C|
                LDX.W #$0000                                   ;808E9F|

         .loop: LDA.L UNREACH_8185AE,X                         ;808EA2|8185AE
                JSR.W StartWindowWipeHdma                      ;808EA6|808EE0
                LDA.L UNREACH_8185AE,X                         ;808EA9|8185AE
                JSR.W StartWindowWipeHdma                      ;808EAD|808EE0
                INX                                            ;808EB0|
                INX                                            ;808EB1|
                CPX.B zp_3A                                    ;808EB2|00003A
                BNE .loop                                      ;808EB4|808EA2
                SEP #$20                                       ;808EB6|
                JSR.W WaitForVBlankStart                       ;808EB8|808DD5
                JSR.W WaitForVBlankEnd                         ;808EBB|808DED
                JSR.W WaitForVBlankStart                       ;808EBE|808DD5
                LDA.B #$00                                     ;808EC1|
