                LDA.B #$09                                     ;808F0C|
                STA.W DMAP3                                    ;808F0E|804330   ; Window-wipe HDMA: DMAP3=$09, BBAD3=$26 ($2126 WH0 write-twice), then HDMAEN=$08 (ch3).
                LDA.B #$26                                     ;808F11|
                STA.W BBAD3                                    ;808F13|804331
                REP #$30                                       ;808F16|
                PLA                                            ;808F18|
                STA.W A1TL3                                    ;808F19|804332
                SEP #$30                                       ;808F1C|
                LDA.B #$01                                     ;808F1E|
                STA.W A1B3                                     ;808F20|804334
                LDA.B #$08                                     ;808F23|
                STA.W HDMAEN                                   ;808F25|80420C   ; enable HDMA channels (HDMAEN)
                LDA.B #$0F                                     ;808F28|
                STA.W INIDISP                                  ;808F2A|802100
                STA.W inidispShadow                            ;808F2D|800330
                REP #$30                                       ;808F30|
                PLX                                            ;808F32|
                RTS                                            ;808F33|


