;== hdr 809091 ==
; ------------------------------------------------------------
;  Hardware math helpers (div / mul)
;    The three /3 routines (PTR16_80E0B1) all use WRDIV
;    ($4204/$4206=3 -> $4214 quot, $4216 rem) but ROUND
;    DIFFERENTLY: 809091 returns A-2*floor(A/3) (~A/3),
;    8090C2 rounds up on rem>=2, 8090E9 truncates (floor).
;    Mul8x8/Mul8x16/Mul16x16 use WRMPY ($4202/$4203 ->
;    $4216). Tiny but executed constantly.
; ------------------------------------------------------------
DivBy3Round_SubA:
                CMP.W #$0000                             ;809091|
                BEQ .exit                                      ;809094|8090C1
                PHA                                            ;809096|
                STA.W WRDIVL                                   ;809097|804204
                SEP #$20                                       ;80909A|
                LDA.B #$03                                     ;80909C|
                STA.W WRDIVB                                   ;80909E|804206
                REP #$20                                       ;8090A1|
                REP #$20                                       ;8090A3|
                PHA                                            ;8090A5|
                PLA                                            ;8090A6|
                NOP                                            ;8090A7|
                LDA.W RDMPYL                                   ;8090A8|804216
                CMP.W #$0002                                   ;8090AB|
                BCS +                                          ;8090AE|8090B6
                LDA.W RDDIVL                                   ;8090B0|804214
                ASL A                                          ;8090B3|
                BRA .cont                                      ;8090B4|8090BB


             +: LDA.W RDDIVL                                   ;8090B6|804214
                ASL A                                          ;8090B9|
                INC A                                          ;8090BA|

         .cont: STA.B refillTmp32                              ;8090BB|000032
                PLA                                            ;8090BD|
                SEC                                            ;8090BE|
                SBC.B refillTmp32                              ;8090BF|000032

         .exit: RTS                                            ;8090C1|


DivBy3Round:
                CMP.W #$0000                                  ;8090C2|
                BEQ .exit                                      ;8090C5|8090E8
                STA.W WRDIVL                                   ;8090C7|804204
                SEP #$20                                       ;8090CA|
                LDA.B #$03                                     ;8090CC|
                STA.W WRDIVB                                   ;8090CE|804206
                REP #$20                                       ;8090D1|
                REP #$20                                       ;8090D3|
                PHA                                            ;8090D5|
                PLA                                            ;8090D6|
                NOP                                            ;8090D7|
                LDA.W RDMPYL                                   ;8090D8|804216
                CMP.W #$0002                                   ;8090DB|
                BCS +                                          ;8090DE|8090E4
                LDA.W RDDIVL                                   ;8090E0|804214
                RTS                                            ;8090E3|


             +: LDA.W RDDIVL                                   ;8090E4|804214
                INC A                                          ;8090E7|

         .exit: RTS                                            ;8090E8|


DivBy3Trunc:
                CMP.W #$0000                                  ;8090E9|
                BEQ .exit                                      ;8090EC|809102
                STA.W WRDIVL                                   ;8090EE|804204
                SEP #$20                                       ;8090F1|
                LDA.B #$03                                     ;8090F3|
                STA.W WRDIVB                                   ;8090F5|804206
                REP #$20                                       ;8090F8|
                REP #$20                                       ;8090FA|
                PHA                                            ;8090FC|
                PLA                                            ;8090FD|
                NOP                                            ;8090FE|
                LDA.W RDDIVL                                   ;8090FF|804214

         .exit: RTS                                            ;809102|

                PHX                                            ;809103|
                STZ.B zp_AE                                    ;809104|0000AE
                LDX.W #$0010                                   ;809106|

         .loop: ASL.B mulMultiplicand                          ;809109|0000AC
                ROL.B zp_AE                                    ;80910B|0000AE
                LDA.B zp_AE                                    ;80910D|0000AE
                SEC                                            ;80910F|
                SBC.B mulMultiplierLo                          ;809110|0000B0
                BCC +                                          ;809112|809116
                STA.B zp_AE                                    ;809114|0000AE

             +: ROL.B mulResult                                ;809116|0000B2
                DEX                                            ;809118|
                BNE .loop                                      ;809119|809109
                PLX                                            ;80911B|
                LDA.B mulResult                                ;80911C|0000B2
                RTS                                            ;80911E|

                PHX                                            ;80911F|
                STZ.B refillTmp32                              ;809120|000032
                LDX.W #$0020                                   ;809122|

        .loop2: ASL.B mulMultiplicand                          ;809125|0000AC
                ROL.B zp_AE                                    ;809127|0000AE
                ROL.B refillTmp32                              ;809129|000032
                LDA.B refillTmp32                              ;80912B|000032
