; ------------------------------------------------------------
;  ComputeButtonEdges
;    Standard edge detector: newly-pressed = (cur EOR prev) AND
;    cur. Updates joy1Pressed/joy2Pressed and stores this frame's
;    state as joy1Prev/joy2Prev for next time.
; ------------------------------------------------------------
ComputeButtonEdges:
                LDA.W joy1Held                                 ;80925C|8003C2   ; joyXPressed = (cur EOR prev) AND cur; then save cur as prev
                EOR.W joy1Prev                                 ;80925F|8003CC
                AND.W joy1Held                                 ;809262|8003C2
                STA.W joy1Pressed                              ;809265|8003C8
                LDA.W joy2Held                                 ;809268|8003C4
                EOR.W joy2Prev                                 ;80926B|8003CE
                AND.W joy2Held                                 ;80926E|8003C4
                STA.W joy2Pressed                              ;809271|8003CA
                LDA.W joy1Held                                 ;809274|8003C2
                STA.W joy1Prev                                 ;809277|8003CC
                LDA.W joy2Held                                 ;80927A|8003C4
                STA.W joy2Prev                                 ;80927D|8003CE
                RTS                                            ;809280|


;======================================================================
; INPUT (JOYPAD) SUBSYSTEM
;======================================================================
; ------------------------------------------------------------
;  ReadJoypads
;    Spin until auto-joypad-read finishes (HVBJOY bit0), then
;    copy JOY1L/JOY2L into joy1Held/joy2Held. A non-standard
;    controller id (low nibble != 0) is treated as 'no input'.
;    In single-player mode joy2Held is forced to 0.
; ------------------------------------------------------------
ReadJoypads:
                LDA.W vblankCmd                                ;809281|800333   ; poll vblankCmd (wait for NMI to consume)
                CMP.W #$0006                                   ;809284|
                BEQ .exit                                      ;809287|8092B8

         .loop: LDA.W HVBJOY                                   ;809289|804212
                BIT.W #$0001                                   ;80928C|
                BNE .loop                                      ;80928F|809289
                LDA.W JOY1L                                    ;809291|804218
                BIT.W #$000F                                   ;809294|
                BEQ +                                          ;809297|80929C
                LDA.W #$0000                                   ;809299|

             +: STA.W joy1Held                                 ;80929C|8003C2   ; store controller 1 state
                LDA.W JOY2L                                    ;80929F|80421A
                BIT.W #$000F                                   ;8092A2|
                BEQ +                                          ;8092A5|8092AA
                LDA.W #$0000                                   ;8092A7|

             +: STA.W joy2Held                                 ;8092AA|8003C4   ; store controller 2 state
                LDA.W numPlayers                               ;8092AD|800308
                CMP.W #$0001                                   ;8092B0|
                BNE .exit                                      ;8092B3|8092B8
                STZ.W joy2Held                                 ;8092B5|8003C4

         .exit: RTS                                            ;8092B8|


; --------------------------------------------------------
;  DelayLoop   [8 ins, returns RTS]
;    callers: ppucfg_808F38, ppucfg_808F57
; --------------------------------------------------------
DelayLoop:
                PHX                                            ;8092B9|   ; busy-wait Y*0x100 iterations

         .loop: LDX.W #$0100                                   ;8092BA|

        .loop2: DEX                                            ;8092BD|
                BNE .loop2                                     ;8092BE|8092BD
                DEY                                            ;8092C0|
                BNE .loop                                      ;8092C1|8092BA
                PLX                                            ;8092C3|
                RTS                                            ;8092C4|

                AND.W #$00FF                                   ;8092C5|
                PHA                                            ;8092C8|
                LSR A                                          ;8092C9|
                LSR A                                          ;8092CA|
                LSR A                                          ;8092CB|
                LSR A                                          ;8092CC|
                JSR.W NibbleToAscii                            ;8092CD|8092D4
                PLA                                            ;8092D0|
                AND.W #$000F                                   ;8092D1|

; --------------------------------------------------------
;  NibbleToAscii   [22 ins, returns RTS]
;    callers: ByteToAsciiHex
;    reads:     ram_0352, ram_0354
;    calls:     vramwr_809302
; --------------------------------------------------------
NibbleToAscii:
                AND.W #$000F                                   ;8092D4|   ; convert low nibble of A to an ASCII/tile hex digit
                CMP.W #$000A                                   ;8092D7|
                BCS +                                          ;8092DA|8092E2
                CLC                                            ;8092DC|
                ADC.W #$0030                                   ;8092DD|
                BRA .cont                                      ;8092E0|8092E6


             +: CLC                                            ;8092E2|
                ADC.W #$0037                                   ;8092E3|

         .cont: PHX                                            ;8092E6|
                PHY                                            ;8092E7|
                AND.W #$00FF                                   ;8092E8|
                SEC                                            ;8092EB|
                SBC.W #$0010                                   ;8092EC|
                CLC                                            ;8092EF|
                ADC.W #$0130                                   ;8092F0|
                LDX.W ram_0352                                 ;8092F3|800352
                LDY.W ram_0354                                 ;8092F6|800354
                JSR.W vramwr_809302                            ;8092F9|809302
                INC.W ram_0352                                 ;8092FC|800352
                PLY                                            ;8092FF|
                PLX                                            ;809300|
                RTS                                            ;809301|


