; --------------------------------------------------------
;  ComputeCameras   [54 ins, returns RTS]
;    callers: ScreenReinitHdmaOff
;    writes:    refillTmp32, playerCamX, playerCamY, mulMultiplicand, mulMultiplierLo, bg2CamXSrc ...
;    reads:     refillTmp32, playerCamX, playerCamY, mulResult, zp_B3, splitYOffset ...
;    calls:     Mul16x16
; --------------------------------------------------------

;== hdr 809E60 ==
; --------------------------------------------------------
; ComputeCameras  [~40 ins, RTS]   (was CODE_FN_809E60)
;   THE camera-compute routine.  Picks the followed object
;   (active viking: X=0, or $03D8/$03DA selected by $19CE/$03E4),
;   reads its world pos $1179,X / $11A1,X, subtracts a half-
;   screen ($80 for X; (224-splitYOffset)/2 for Y) so the
;   object is centred, clamps to [0, camMaxX/Y] ($19A3/$19A5),
;   and stores the player camera in playerCamX/playerCamY.
;   It then derives the BG2 (parallax) camera by hardware-
;   multiplying the player cam by parallaxScaleX/Y ($1A06/$1A08)
;   via $809186, storing hi bytes in bg2CamXSrc/YSrc ($16A5/$16A7)
;   and lo/fractions in $16B1/$16B3.
;
;   Pipeline (main loop @ $809B5D..$809B66):
;     ComputeCameraBounds $809E0D  -> camMaxX/Y
;     ComputeCameras      $809E60  -> playerCam + bg2CamSrc
;     LatchBgScroll       $80BFE0  -> PPU scroll
;   (SnapshotCameras $80BFBB runs in the OTHER caller path
;    -- $808081/$80A0A3 -- writing $16B5.. from playerCamX/$16A5.)
;   caller: $809B60
; --------------------------------------------------------
ComputeCameras:
                LDX.W #$0000                                 ;809E60|
                LDA.W ram_19CE                                 ;809E63|8019CE
                AND.W #$00FF                                   ;809E66|
                BEQ .skip                                      ;809E69|809E76
                LDX.W inputAux1                                ;809E6B|8003D8
                LDA.W ram_03E4                                 ;809E6E|8003E4
                BEQ .skip                                      ;809E71|809E76
                LDX.W inputAux2                                ;809E73|8003DA

         .skip: LDA.W objField_1179,X                          ;809E76|801179
                SEC                                            ;809E79|
                SBC.W #$0080                                   ;809E7A|
                BMI +                                          ;809E7D|809E81
                BCS .skip2                                     ;809E7F|809E84

             +: LDA.W #$0000                                   ;809E81|

        .skip2: CMP.W camMaxX                                  ;809E84|8019A3
                BCC +                                          ;809E87|809E8C
                LDA.W camMaxX                                  ;809E89|8019A3

             +: STA.B playerCamX                               ;809E8C|000044   ; playerCamX = clamp(followObjX-128, 0, camMaxX)
                LDA.W #$00E0                                   ;809E8E|
                SEC                                            ;809E91|
                SBC.W splitYOffset                             ;809E92|800340
                LSR A                                          ;809E95|
                STA.B refillTmp32                              ;809E96|000032
                LDA.W objField_11A1,X                          ;809E98|8011A1
                SEC                                            ;809E9B|
                SBC.B refillTmp32                              ;809E9C|000032
                BMI +                                          ;809E9E|809EA2
                BCS .skip3                                     ;809EA0|809EA5

             +: LDA.W #$0000                                   ;809EA2|

        .skip3: CMP.W camMaxY                                  ;809EA5|8019A5
                BCC +                                          ;809EA8|809EAD
                LDA.W camMaxY                                  ;809EAA|8019A5

             +: STA.B playerCamY                               ;809EAD|000046   ; playerCamY = clamp(followObjY-(224-splitYOffset)/2, 0, camMaxY)
                LDA.W parallaxScaleX                           ;809EAF|801A06
                STA.B mulMultiplicand                          ;809EB2|0000AC
                LDA.B playerCamX                               ;809EB4|000044
                STA.B mulMultiplierLo                          ;809EB6|0000B0
                JSR.W Mul16x16                                 ;809EB8|809186
                LDA.B mulResult                                ;809EBB|0000B2
                AND.W #$00FF                                   ;809EBD|
                STA.W bg2CamXFrac                              ;809EC0|8016B1
                LDA.B zp_B3                                    ;809EC3|0000B3
                STA.W bg2CamXSrc                               ;809EC5|8016A5   ; bg2CamXSrc = hi(playerCamX * parallaxScaleX) -- BG2 parallax
                LDA.W parallaxScaleY                           ;809EC8|801A08
                STA.B mulMultiplicand                          ;809ECB|0000AC
                LDA.B playerCamY                               ;809ECD|000046
                STA.B mulMultiplierLo                          ;809ECF|0000B0
                JSR.W Mul16x16                                 ;809ED1|809186
                LDA.B mulResult                                ;809ED4|0000B2
                AND.W #$00FF                                   ;809ED6|
                STA.W bg2CamYFrac                              ;809ED9|8016B3
                LDA.B zp_B3                                    ;809EDC|0000B3
                STA.W bg2CamYSrc                               ;809EDE|8016A7
                RTS                                            ;809EE1|


