; --------------------------------------------------------
;  SnapshotCameras   [15 ins, returns RTS]
;    callers: vbwait_808081, sub_80A0A3
;    writes:    scrollDirty, bg1CamX, bg1CamY, bg2CamX, bg2CamY
;    reads:     playerCamX, playerCamY, splitYOffset, bg2CamXSrc, bg2CamYSrc
; --------------------------------------------------------

;== hdr 80BFBB ==
; --------------------------------------------------------
; SnapshotCameras  [15 ins, RTS]   (was sub_80BFBB)
;   Latches this frame's computed cameras into the BG scroll-
;   camera shadows that LatchBgScroll consumes, and raises
;   scrollDirty so the latch recomputes the scroll shadows.
;
;     bg1CamX ($16B5) <- playerCamX (playerCamX)
;     bg1CamY ($16B7) <- playerCamY (playerCamY) - splitYOffset ($0340)
;     bg2CamX ($16B9) <- bg2CamXSrc ($16A5)   [parallax-scaled]
;     bg2CamY ($16BB) <- bg2CamYSrc ($16A7) - splitYOffset
;     scrollDirty ($16A3) <- 1
;
;   splitYOffset is $30 (48px) in split layout, else 0 -- so in
;   the split mode both BGs are pushed down by 48 px here.
;   NOTE: this routine is NOT exercised in slice_scroll.txt;
;   its stores are confirmed only in the full trace.
;   callers: $8080AF/$8080CF/$8080F5 (vbwait $808081),
;            $80A0C1/$80A0DF/$80A106 (sub $80A0A3)
; --------------------------------------------------------
SnapshotCameras:
                LDA.B playerCamX                          ;80BFBB|000044
                STA.W bg1CamX                                  ;80BFBD|8016B5
                LDA.B playerCamY                               ;80BFC0|000046
                SEC                                            ;80BFC2|
                SBC.W splitYOffset                             ;80BFC3|800340   ; - splitYOffset $0340 ($30 in split layout, else 0): shift bg1CamY down
                STA.W bg1CamY                                  ;80BFC6|8016B7
                LDA.W bg2CamXSrc                               ;80BFC9|8016A5
                STA.W bg2CamX                                  ;80BFCC|8016B9
                LDA.W bg2CamYSrc                               ;80BFCF|8016A7
                SEC                                            ;80BFD2|
                SBC.W splitYOffset                             ;80BFD3|800340   ; - splitYOffset: shift bg2CamY down by same amount
                STA.W bg2CamY                                  ;80BFD6|8016BB
                LDA.W #$0001                                   ;80BFD9|
                STA.W scrollDirty                              ;80BFDC|8016A3   ; scrollDirty=1 -> LatchBgScroll will recompute scroll shadows
                RTS                                            ;80BFDF|


; --------------------------------------------------------
;  LatchBgScroll  ==  LatchBgScroll   [37 ins, returns RTS]
;    callers: VBlank_Flush_DmaA, VBlank_Flush_DmaB, VBlank_Flush_Tilemap, ScreenReinitHdmaOff
; ------------------------------------------------------------
;  The camera -> PPU scroll latch. Two halves:
;
;  (1) If scrollDirty ($16A3) is set (camera moved this frame),
;      recompute the BG scroll shadows from the cameras:
;         bg1Scroll = bg1Cam ($16B5/$16B7) + scrollAdjust ($03A2/$03A4)
;         bg2Scroll ($16C1/$16C3) = bg2Cam ($16B9/$16BB)
;      then clear scrollDirty.  (scrollAdjust is a per-frame nudge --
;      shake / sub-pixel / parallax; INFERRED.)
;
;  (2) Push the shadows to the PPU scroll registers:
;         BG1HOFS/BG1VOFS <- bg1Scroll   (write-twice, lo then hi)
;         BG2HOFS/BG2VOFS <- bg2Scroll
;
;  >> SPLIT-SCREEN SEAM: when gameModeFlags bit0 (split layout) is
;     SET, the BG1 scroll write is SKIPPED (BNE LatchBG2Scroll) -- BG1
;     is then driven mid-frame by the raster IRQ / HDMA path
;     instead. BG2 scroll is always written here. This is exactly
;     where an HDMA-per-region scroll scheme takes over BG1. <<
;
;    writes HW: BG1HOFS, BG1VOFS, BG2HOFS, BG2VOFS
;    writes:    scrollDirty, bg1ScrollX/Y, bg2ScrollX/Y
;    reads:     scrollAdjustX/Y, bg1CamX/Y, bg2CamX/Y, gameModeFlags
; --------------------------------------------------------
LatchBgScroll:
                LDA.W scrollDirty                              ;80BFE0|8016A3   ; scrollDirty: did the camera move?   ; latch BG1 scroll shadow $16BD -> BG1HOFS $210D
                BEQ loc_80C008                                 ;80BFE3|80C008   ; no -> skip recompute, just re-push shadows
                STZ.W scrollDirty                              ;80BFE5|8016A3   ; consume the dirty flag
                LDA.W bg1CamX                                  ;80BFE8|8016B5   ; bg1CamX (world camera X for BG1)
                CLC                                            ;80BFEB|
                ADC.W scrollAdjustX                            ;80BFEC|8003A2   ; + scrollAdjustX (per-frame nudge)   ; bg1ScrollX = bg1CamX + scrollAdjustX (BG1 only; BG2 gets no adjust)

loc_80BFEF:
                STA.W bg1ScrollXLo                             ;80BFEF|8016BD   ; -> BG1 scroll X shadow
                LDA.W bg1CamY                                  ;80BFF2|8016B7   ; bg1CamY
                CLC                                            ;80BFF5|
                ADC.W scrollAdjustY                            ;80BFF6|8003A4   ; + scrollAdjustY
                STA.W bg1ScrollYLo                             ;80BFF9|8016BF   ; -> BG1 scroll Y shadow
                LDA.W bg2CamX                                  ;80BFFC|8016B9   ; bg2CamX
                STA.W bg2ScrollXLo                             ;80BFFF|8016C1   ; -> BG2 scroll X shadow   ; bg2ScrollX = bg2CamX directly (no scrollAdjust on BG2)
                LDA.W bg2CamY                                  ;80C002|8016BB   ; bg2CamY
                STA.W bg2ScrollYLo                             ;80C005|8016C3   ; -> BG2 scroll Y shadow

loc_80C008:
                SEP #$30                                       ;80C008|
                LDA.W gameModeFlags                            ;80C00A|8019E3
                BIT.B #$01                                     ;80C00D|         ; split-layout bit set?   ; split-layout bit: if set, skip BG1 scroll latch (raster/HDMA owns BG1)

;== hdr 80C00F ==
;  >>> SPLIT-SCREEN SEAM <<<
;  gameModeFlags ($19E3) bit0 == 1  =>  BNE $80C029 skips the
;  entire BG1 scroll push below.  In the normal (full-screen)
;  layout bit0==0 and BG1 is latched here from the shadows.
;  When the split is active the raster IRQ / HDMA path is
;  expected to own BG1 scroll instead.
;  BG2 scroll ($80C029) is ALWAYS written.
;  TRACE (slice_scroll.txt): $19E3=$01 -> branch taken
;         (BG1 skipped) 13x; $19E3=$02 -> BG1 written
;         ($80C014 STA BG1HOFS) 97x.
                BNE LatchBG2Scroll                             ;80C00F|80C029   ; YES -> skip BG1 (HDMA/raster owns it)
                LDA.W bg1ScrollXLo                             ;80C011|8016BD
                STA.W BG1HOFS                                  ;80C014|80210D   ; BG1 X low   ; BG1HOFS write-twice (lo here, hi at $80C01A) -- only when NOT split
                LDA.W bg1ScrollXHi                             ;80C017|8016BE
                STA.W BG1HOFS                                  ;80C01A|80210D   ; BG1 X high (write-twice)
                LDA.W bg1ScrollYLo                             ;80C01D|8016BF
                STA.W BG1VOFS                                  ;80C020|80210E   ; BG1 Y low
                LDA.W bg1ScrollYHi                             ;80C023|8016C0
                STA.W BG1VOFS                                  ;80C026|80210E   ; BG1 Y high

LatchBG2Scroll:
                LDA.W bg2ScrollXLo                         ;80C029|8016C1
                STA.W BG2HOFS                                  ;80C02C|80210F   ; BG2 X low   ; BG2HOFS write-twice (always, even in split layout)
                LDA.W bg2ScrollXHi                             ;80C02F|8016C2
                STA.W BG2HOFS                                  ;80C032|80210F   ; BG2 X high (write-twice)
                LDA.W bg2ScrollYLo                             ;80C035|8016C3
                STA.W BG2VOFS                                  ;80C038|802110   ; BG2 Y low
                LDA.W bg2ScrollYHi                             ;80C03B|8016C4
                STA.W BG2VOFS                                  ;80C03E|802110   ; BG2 Y high
                REP #$30                                       ;80C041|
                RTS                                            ;80C043|


; --------------------------------------------------------
;  SetPpuUpdateBits   [3 ins, returns RTS]
;    callers: RefillColumnRight, RefillColumnLeft, RefillRowDown, RefillRowUp, sub_80C825, sub_80C84C, +2 more
;    writes:    tilemapUploadMask
;    reads:     tilemapUploadMask
; --------------------------------------------------------
SetPpuUpdateBits:
