; --------------------------------------------------------
;  RefillTilemapOnScroll   [29 ins, returns RTS]
;    callers: sub_80C080
;    writes:    refillTmp32, refillLastCamX, refillLastCamY
;    reads:     refillTmp32, playerCamX, playerCamY, refillLastCamX, refillLastCamY
;    calls:     RefillRowUp, RefillRowDown, RefillColumnLeft, RefillColumnRight
; --------------------------------------------------------

;== hdr 80C176 ==
; ============================================================
;  RefillTilemapOnScroll  (scroll-driven BG tilemap streaming)
; ============================================================
;  Called every frame from the vblank-wait loop:
;    vbwait_808081 -> sub_80C080 -> here.
;  Compares the camera latched after the previous refill
;  (refillLastCamX $16A9 / refillLastCamY $16AB, stored RAW)
;  against the current camera ($44 = camX, $46 = camY):
;    * Y is snapped to the 8px metatile-ROW grid (AND #$FFF8).
;      A change of one step => refill a ROW (down=$80C20C,
;      up=$80C269).
;    * X is snapped to the 16px metatile-COLUMN grid
;      (AND #$FFF0). A change => refill a COLUMN
;      (right=$80C1B9, left=$80C1E4).
;  After dispatch it stores the RAW current camera back into
;  $16A9/$16AB (the masking is applied at compare time, not
;  when latching) so only NEW grid crossings trigger work.
;
;  The SNES BG tilemap is a 32x32 (mod-32) scrolling window;
;  as the camera moves one metatile, exactly one off-screen
;  column/row of the 32-wide map is overwritten with fresh
;  tiles, and the hardware's wrap makes it appear at the far
;  edge. The mod-32 quadrant-select math lives in
;  BuildTilemapColumn ($80C2E5 AND #$003F / $80C2F0 AND #$001F).

RefillTilemapOnScroll:

              ; Vertical refill
                     ;   LDA.W modFlags                                 ;INSERT|
                     ;   BIT.W #$0001                                   ;INSERT|
                     ;   BEQ .original                                  ;INSERT|

                     ; ; modded logic:
                     ;   LDA.W refillLastCamY                           ;INSERT|
                     ;   AND.W #$FFFC                                   ;INSERT|
                     ;   STA.B refillTmp32                              ;INSERT|
                     ;   LDA.B playerCamY                               ;INSERT|
                     ;   AND.W #$FFFC                                   ;INSERT|
                     ;   BRA ++                                         ;INSERT|


    .originalY: LDA.W refillLastCamY                           ;80C176|8016AB   
                AND.W #$FFF8                                   ;80C179|         
                STA.B refillTmp32                              ;80C17C|000032   
                LDA.B playerCamY                               ;80C17E|000046   
                AND.W #$FFF8                                   ;80C180|         

            ++: SEC                                            ;80C183|
                SBC.B refillTmp32                              ;80C184|000032   ; A = new snapped camY - old snapped camY: 0 = same row, nonzero = crossed at least one row
                BEQ .refillX                                   ;80C186|80C192   ; no vertical crossing -> skip straight to the horizontal check
                BPL +                                          ;80C188|80C18F   ; positive delta = camera moved DOWN -> refill the row revealed at the bottom
                JSR.W RefillRowUp                              ;80C18A|80C269   ; negative delta = camera moved UP -> refill the row revealed at the top
                BRA .refillX                                   ;80C18D|80C192


             +: JSR.W RefillRowDown                            ;80C18F|80C20C


                ;Horizontal refill

                ; Mod check:
      .refillX: LDA.W modFlags                                 ;INSERT|         ; check to see if the mod is enabled
                BIT.W #$0001                                   ;INSERT|
                BEQ .originalX                                 ;INSERT|


                ; modded logic:                                                 ; if it is, perform modded logic.
                LDA.W refillLastCamX                           ;INSERT|         ; load the last camera X position
                AND.W #$FFF8                                   ;INSERT|         ; align to half metatile instead of full metatile
                STA.B refillTmp32                              ;INSERT|         ; store to tmp var for subtraction
                LDA.B playerCamX                               ;INSERT|         ; load the current camera X position
                AND.W #$FFF8                                   ;INSERT|         ; align to half metatile instead of full metatile
                SEC                                            ;INSERT|         ; set carry for subtraction
                SBC.B refillTmp32                              ;INSERT|         ; subtract the floored values: 

                BEQ .updateLastCam                             ;INSERT|         ; if the difference is zero, no horizontal movement occurred, so skip the refill logic

                BPL +                                          ;INSERT|         ; if the difference is positive, the camera moved right

                JSR.W RefillColumnLeftMod                      ;INSERT|         ; otherwise, the camera moved left, so refill the left column
                BRA .updateLastCam                             ;INSERT|         ; after handling the refill, update the last camera position

             +: JSR.W RefillColumnRightMod                     ;INSERT|         ;
                BRA .updateLastCam                             ;INSERT|         ; after handling the refill, update the last camera position


                ; Original logic:                                               ; if the mod is not active, fall back to the original logic
    .originalX: LDA.W refillLastCamX                           ;80C192|8016A9   ; load the last camera X position
                AND.W #$FFF0                                   ;80C195|         ; align to the metatile boundary
                STA.B refillTmp32                              ;80C198|000032   ; store to tmp var for subtraction
                LDA.B playerCamX                               ;80C19A|000044   ; load the current camera X position
                AND.W #$FFF0                                   ;80C19C|         ; align to the metatile boundary
                SEC                                            ;80C19F|         ; set carry flag for subtraction
                SBC.B refillTmp32                              ;80C1A0|000032   ; subract the floored values: 

                BEQ .updateLastCam                             ;80C1A2|80C1AE   ; if the difference is zero, no horizontal movement occurred, so skip the refill logic
                
                BPL +                                          ;80C1A4|80C1AB   ; if the difference is positive, the camera moved right
                
                JSR.W RefillColumnLeft                         ;80C1A6|80C1E4   ; otherwise, the camera moved left, so refill the left column
                BRA .updateLastCam                             ;80C1A9|80C1AE   ; after handling the refill, update the last camera position

             +: JSR.W RefillColumnRight                        ;80C1AB|80C1B9


                ; update the last camera X position for the next frame's comparison
.updateLastCam: LDA.B playerCamX                               ;80C1AE|000044   ; load the current camera X position
                STA.W refillLastCamX                           ;80C1B0|8016A9   ; and store it as the last camera X position for the next frame's comparison
                LDA.B playerCamY                               ;80C1B3|000046   ; load the current camera Y position
                STA.W refillLastCamY                           ;80C1B5|8016AB   ; and store it as the last camera Y position for the next frame's comparison
                RTS                                            ;80C1B8|


; --------------------------------------------------------
;  RefillColumnRight   [19 ins, returns ?]
;    callers: RefillTilemapOnScroll
;    writes:    refillColTileX
;    reads:     playerCamY, refillColTileX, refillRowTileY
;    calls:     BuildTilemapCol, SetPpuUpdateBits, loc_80EEB1
; --------------------------------------------------------

;== hdr 80C1B9 ==
; --- RefillColumnRight (camera moved right one metatile) ---
;  refillColTileX ($16C5) += 2 (two 8px tiles per 16px col).
;  The column actually uploaded is the OFF-SCREEN one to the
;  right of the visible window: tileX = $16C5 + $0022
;  (real opcode at $80C1C5 is ADC.W #$0022 -- the +$22 is the
;   look-ahead distance to the new column). BuildTilemapColumn
;  stages it; bit0 of the PPU-update bitfield ($03AE) queues
;  the DMA; $80EEB1 sets the new column's sprite clip window.
RefillColumnRight:
                LDA.W refillColTileX                           ;80C1B9|8016C5   ; step 1: advance the "leftmost visible column" tracker by one metatile (2 tiles = 16px)
                INC A                                          ;80C1BC|
                INC A                                          ;80C1BD|
                STA.W refillColTileX                           ;80C1BE|8016C5
                LDA.W refillColTileX                           ;80C1C1|8016C5   ; step 2: compute the tile-X of the column to actually STAGE: the new
                CLC                                            ;80C1C4|         ; off-screen edge is a fixed look-ahead distance to the right of the
                ADC.W #$0022                                   ;80C1C5|         ; off-screen column tileX = refillColTileX + $22 (real opcode ADC.W #$0022; the prompt's +$10 is wrong)
                TAX                                            ;80C1C8|         ; X = tile-X argument to BuildTilemapCol/BuildTilemapColumn
                LDY.W refillRowTileY                           ;80C1C9|8016C7   ; step 3: Y = top tile-Y of the column, normally the current row tracker...
                LDA.B playerCamY                               ;80C1CC|000046
                AND.W #$0008                                   ;80C1CE|         ; ...but if camY isn't on an 8px row boundary (mid-row scroll), back Y up
                BNE +                                          ;80C1D1|80C1D5   ; one metatile-row so the staged column still starts flush with the
                DEY                                            ;80C1D3|         ; currently-visible top row instead of one row too low
                DEY                                            ;80C1D4|

             +: LDA.W #$0022                                   ;80C1D5|         ; step 4: A = same +$22 offset, passed to BuildTilemapCol as the signed
                JSR.W BuildTilemapCol                          ;80C1D8|80C2BE   ; column offset used for the VRAM destination/wrap math (see its header)
                LDA.W #$0001                                   ;80C1DB|         ; step 5: flag bit0 = "a column DMA is ready" for VBlank_Flush_Tilemap
                JSR.W SetPpuUpdateBits                         ;80C1DE|80C044
                JMP.W loc_80EEB1                               ;80C1E1|80EEB1   ; step 6: tail-call into the sprite/object clip-window setup for the right edge


; --------------------------------------------------------
;  RefillColumnLeft   [18 ins, returns ?]
;    callers: RefillTilemapOnScroll
;    writes:    refillColTileX
;    reads:     playerCamY, refillColTileX, refillRowTileY
;    calls:     BuildTilemapCol, SetPpuUpdateBits, loc_80EEA1
; --------------------------------------------------------
RefillColumnLeft:
                LDA.W refillColTileX                     ;80C1E4|8016C5   ; step 1: move the "leftmost visible column" tracker back one metatile
                DEC A                                          ;80C1E7|
                DEC A                                          ;80C1E8|
                STA.W refillColTileX                           ;80C1E9|8016C5
                LDX.W refillColTileX                           ;80C1EC|8016C5   ; step 2: X = tile-X of the column to stage: two tiles further LEFT than
                DEX                                            ;80C1EF|         ; the (already-decremented) tracker -- i.e. the new off-screen column
                DEX                                            ;80C1F0|         ; that just scrolled past the left edge of the visible window
                LDY.W refillRowTileY                           ;80C1F1|8016C7   ; step 3: same mid-row correction as RefillColumnRight (see its comments)
                LDA.B playerCamY                               ;80C1F4|000046
                AND.W #$0008                                   ;80C1F6|
                BNE +                                          ;80C1F9|80C1FD
                DEY                                            ;80C1FB|
                DEY                                            ;80C1FC|

             +: LDA.W #$FFFE                                   ;80C1FD|         ; step 4: A = -2, the signed column offset (this column is 2 tiles LEFT
                JSR.W BuildTilemapCol                        ;80C200|80C2BE   ; of refillColTileX) passed into BuildTilemapCol's wrap/dest math
                LDA.W #$0001                                   ;80C203|         ; step 5: same column-DMA-ready flag as RefillColumnRight
                JSR.W SetPpuUpdateBits                         ;80C206|80C044
                JMP.W loc_80EEA1                               ;80C209|80EEA1   ; step 6: tail-call into the sprite/object clip-window setup for the left edge

; MODDED FUNCTIONS:

RefillColumnLeftMod:
                LDA.B playerCamX                               ;INSERT|
                LSR A                                          ;INSERT|
                LSR A                                          ;INSERT|
                LSR A                                          ;INSERT|

                AND.W #$FFFE                                   ;INSERT|
                LDX.B playerCamX                               ;INSERT|
                BPL +                                          ;INSERT|
                ORA.W #$E000                                   ;INSERT|

             +: STA.W refillColTileX                           ;INSERT|

                LDA.B playerCamX                               ;INSERT|
                AND.W #$0008                                   ;INSERT|
                BNE .firstHalf                                 ;INSERT|

                LDX.W refillColTileX                           ;INSERT|
                INX                                            ;INSERT|
                INX                                            ;INSERT|
                LDY.W refillRowTileY                           ;INSERT|
                LDA.B playerCamY
                AND.W #$0008                                   ;INSERT|
                BNE +                                          ;INSERT|
                DEY
                DEY

             +: LDA.W #$0002                                   ;INSERT|
                JSR.W BuildTilemapCol                          ;INSERT|
                LDA.W #$0001                                   ;INSERT|
                JSR.W SetPpuUpdateBits                         ;INSERT|
                JMP.W loc_80EEA1                               ;INSERT|


    .firstHalf: LDA.B playerCamX                               ;INSERT|
                SEC                                            ;INSERT|
                SBC.W refillLastCamX                           ;INSERT|
                CMP.W #$0009                                   ;INSERT|
                BCC .exit                                      ;INSERT|
                LDX.W refillColTileX                           ;INSERT|
                INX                                            ;INSERT|
                INX                                            ;INSERT|
                INX                                            ;INSERT|
                INX                                            ;INSERT|
                LDY.W refillRowTileY                           ;INSERT|
                LDA.W #$0004                                   ;INSERT|
                JSR.W BuildTilemapCol                          ;INSERT|
                LDA.W #$0001                                   ;INSERT|
                JSR.W SetPpuUpdateBits                         ;INSERT|
                JMP.W loc_80EEA1                               ;INSERT|


         .exit: RTS                                            ;INSERT|


RefillColumnRightMod:
                LDA.B playerCamX                               ;INSERT|
                LSR A                                          ;INSERT|
                LSR A                                          ;INSERT|
                LSR A                                          ;INSERT|


                AND.W #$FFFE                                   ;INSERT|
                LDX.B playerCamX                               ;INSERT|
                BPL +                                          ;INSERT|
                ORA.W #$E000                                   ;INSERT|                                                                      ;INSERT|
             +: STA.W refillColTileX                           ;INSERT|


                LDA.B playerCamX                               ;INSERT|
                AND.W #$0008                                   ;INSERT|
                BEQ .firstHalf                                 ;INSERT|


                LDA.W refillColTileX                           ;INSERT|
                CLC                                            ;INSERT|
                ADC.W #$0022                                   ;INSERT|
                TAX                                            ;INSERT|
                LDY.W refillRowTileY                           ;INSERT|
                LDA.B playerCamY                               ;INSERT|
                AND.W #$0008                                   ;INSERT|
                BNE +                                          ;INSERT|
                DEY                                            ;INSERT|
                DEY                                            ;INSERT|

             +: LDA.W #$0022                                   ;INSERT|

                JSR.W BuildTilemapCol                          ;INSERT|
                LDA.W #$0001                                   ;INSERT|
                JSR.W SetPpuUpdateBits                         ;INSERT|
                JMP.W loc_80EEB1                               ;INSERT|


    .firstHalf: LDA.B playerCamX                               ;INSERT|
                SEC                                            ;INSERT|
                SBC.W refillLastCamX                           ;INSERT|
                CMP.W #$0009                                   ;INSERT|
                BCC .exit                                      ;INSERT|

                LDA.W refillColTileX                           ;INSERT|
                CLC                                            ;INSERT|
                ADC.W #$0020                                   ;INSERT|
                TAX                                            ;INSERT|
                LDY.W refillRowTileY                           ;INSERT|
                LDA.B playerCamY                               ;INSERT|
                AND.W #$0008                                   ;INSERT|
                BNE +                                          ;INSERT|
                DEY                                            ;INSERT|
                DEY                                            ;INSERT|

             +: LDA.W #$0020                                   ;INSERT|

                JSR.W BuildTilemapCol                          ;INSERT|
                LDA.W #$0001                                   ;INSERT|
                JSR.W SetPpuUpdateBits                         ;INSERT|
