; --------------------------------------------------------
;  UploadTilemapColumn   [55 ins, returns RTS]
;    callers: ProcessTilemapEdits, FillTilemapFull
;    writes HW: A1B0, A1TL0, BBAD0, DASL0, DMAP0, MDMAEN, VMADDL, VMAIN
;    reads:     colDmaVramDest0, colDmaLen0, colDmaVramDest1, colDmaLen1
; --------------------------------------------------------

;== hdr 80C517 ==
; --- UploadTilemapColumn: DMA staged column to BG VRAM -----
;  Runs in NMI/vblank (queued via $03AE bit0). VMAIN=$81
;  (address increments after the HIGH byte, +32 word step) so
;  consecutive writes walk DOWN a tilemap column. DMA ch.0,
;  mode 1 (write $2118/$2119), A-bus src in bank $7E.
;    even half: src colStageBg1Even($16F5) -> $16CD
;    odd  half: src colStageBg1Odd ($1735) -> $16CD+1
;  each split into the main run and the wrapped run when the
;  column crosses the 32-col seam ($16D3 != 0). VMAIN reset
;  to $80 on exit.
UploadTilemapColumn:
                SEP #$30                                  ;80C517|
                LDA.B #$81                                     ;80C519|   ; VMAIN=$81: address increments on high-byte write with +32-word step => writes walk down a tilemap column
                STA.W VMAIN                                    ;80C51B|802115   ; VMAIN=$81: increment VRAM addr after high-byte write, step=+1 word
                LDA.B #$01                                     ;80C51E|
                STA.W DMAP0                                    ;80C520|804300   ; DMAP0=$01: GP-DMA transfer mode 1 (write A -> 2 regs VMDATAL/H)
                LDA.B #$18                                     ;80C523|
                STA.W BBAD0                                    ;80C525|804301   ; BBAD0=$18: DMA dest B-bus = VMDATA $2118
                REP #$30                                       ;80C528|
                LDA.W colDmaVramDest0                          ;80C52A|8016CD
                STA.W VMADDL                                   ;80C52D|802116   ; set VRAM addr (low) for upcoming write
                LDA.W #$16F5                                   ;80C530|
                STA.W A1TL0                                    ;80C533|804302
                LDA.W colDmaLen0                               ;80C536|8016CF
                STA.W DASL0                                    ;80C539|804305
                SEP #$30                                       ;80C53C|
                LDA.B #$7E                                     ;80C53E|
                STA.W A1B0                                     ;80C540|804304   ; A1B0=$7E: DMA source bank = WRAM $7E (vramCol* staging buffers)
                LDA.B #$01                                     ;80C543|
                STA.W MDMAEN                                   ;80C545|80420B   ; trigger GP-DMA (MDMAEN)   ; MDMAEN=$01: fire channel-0 GP-DMA (trace A:0001; Mesen shows '$8D' = open-bus readback of write-only $420B, not the written value)
                LDA.W colDmaLen1                               ;80C548|8016D3
                BEQ .skip                                      ;80C54B|80C562
                REP #$30                                       ;80C54D|
                LDA.W colDmaVramDest1                          ;80C54F|8016D1
                STA.W VMADDL                                   ;80C552|802116   ; set VRAM addr (low) for upcoming write
                LDA.W colDmaLen1                               ;80C555|8016D3
                STA.W DASL0                                    ;80C558|804305
                SEP #$30                                       ;80C55B|
                LDA.B #$01                                     ;80C55D|
                STA.W MDMAEN                                   ;80C55F|80420B   ; trigger GP-DMA (MDMAEN)

         .skip: REP #$30                                       ;80C562|
                LDA.W colDmaVramDest0                          ;80C564|8016CD
                INC A                                          ;80C567|
                STA.W VMADDL                                   ;80C568|802116   ; set VRAM addr (low) for upcoming write
                LDA.W #$1735                                   ;80C56B|
                STA.W A1TL0                                    ;80C56E|804302
                LDA.W colDmaLen0                               ;80C571|8016CF
                STA.W DASL0                                    ;80C574|804305
                SEP #$30                                       ;80C577|
                LDA.B #$01                                     ;80C579|
                STA.W MDMAEN                                   ;80C57B|80420B   ; trigger GP-DMA (MDMAEN)
                LDA.W colDmaLen1                               ;80C57E|8016D3
                BEQ .skip2                                     ;80C581|80C599
                REP #$30                                       ;80C583|
                LDA.W colDmaVramDest1                          ;80C585|8016D1
                INC A                                          ;80C588|
                STA.W VMADDL                                   ;80C589|802116   ; set VRAM addr (low) for upcoming write
                LDA.W colDmaLen1                               ;80C58C|8016D3
                STA.W DASL0                                    ;80C58F|804305
                SEP #$30                                       ;80C592|
                LDA.B #$01                                     ;80C594|
                STA.W MDMAEN                                   ;80C596|80420B   ; trigger GP-DMA (MDMAEN)

        .skip2: LDA.B #$80                                     ;80C599|
                STA.W VMAIN                                    ;80C59B|802115
                REP #$30                                       ;80C59E|
                RTS                                            ;80C5A0|


