                ADC.W splitYOffset                             ;80E0CB|800340
                CLC                                            ;80E0CE|
                SBC.B playerCamY                               ;80E0CF|000046
                CMP.W #$00E0                                   ;80E0D1|
                BCC +                                          ;80E0D4|80E0DE
                CMP.W #$FFE0                                   ;80E0D6|
                BCC .skip                                      ;80E0D9|80E11B
                AND.W #$00FF                                   ;80E0DB|

             +: XBA                                            ;80E0DE|
                STA.B refillTmp32                              ;80E0DF|000032
                TXA                                            ;80E0E1|
