                CMP.W #$FFC0                                   ;80E0F0|
                BCC .skip                                      ;80E0F3|80E11B
                AND.W #$00FF                                   ;80E0F5|
                ORA.B refillTmp32                              ;80E0F8|000032
                STA.W oamBuildLo,X                             ;80E0FA|800571
